        "update_v112_date": "April 30, 2026 | 10:15 AM",
        "update_v112_ver": "v1.1.2 (Linguistic Parity)",
        "update_v112_title": "جامع کثیر لسانی مدد تہٕ عالمی رسائی",
        "update_v112_desc": "اسہِ چھُ پورہ لاجسٹک پلیٹ فارمس منز مکمل لسانی برابری حاصل کئرمژ۔ مینیجر، ڈرائیور تہٕ صارِف ہیکن اب پئنِہ مادری زبانن منز پورٹلس سئتی رابطہ کئرتھ۔",
        "update_v112_b1": "15+ علاقائی زبانن منز مکمل سپورٹ، بشمول کٲشُر، ہندی، تہٕ بٲنٛگلہ۔",
        "update_v112_b2": "<strong>لوکلائزیشن:</strong> ہر ڈیش بورڈ، ٹیبل ہیدر، بٹن تہٕ سسٹم نوٹیفکیشن چھُ اب پئنِہ زبانہِ منز دٔستیاب۔",
        "update_v112_b3": "<strong>رئیل ٹائم اپڈیٹ:</strong> بغیر پیج ری لوڈ کئرتھ چھُ زبان تبدیل گژھان۔",
        "update_v112_b4": "<strong>وائس کمانڈ:</strong> ڈرائیورن ہٕنٛدِ حفاظتِ خاطرٕ چھِ وائس کمانڈ علاقائی زبانن منز دٔستیاب۔",
        "update_v112_impact_desc": "یہِ اپڈیٹ چھُ لسانی رکاوٹن ختم کران، یمہِ سئتی پیشہ ورانہ لاجسٹک انتظام ہر کنس خآطرہ آسان گژھان:",
        "update_v112_i1": "عالمی رسائی: ہر جایِک صارِف ہیکہِ اب پئنِہ مادری زبانہِ منز پورٹل زیادہ آزادانہ طور پئٹھ اِستعمال کئرتھ۔",
        "update_v112_i2": "آزادی: ڈرائیور ہیکن اب پانہِ نیویگیٹ کئرتھ تہٕ پئنِہ والٹ چلاوِتھ۔",
        "update_v112_i3": "شفافیت: مقامی مالیاتی ہیدر تہٕ اسمارٹ کنٹریکٹ شرطہ چھِ شفافیت تہٕ اعتماد یقینی بناوان۔",
        "update_v112_i4": "عالمی معیار: عالمی ٹیکنالوجی تہٕ علاقائی تجربہ کار تال میل۔",
        "tag_localization": "مقامی بنانا",
        "tag_accessibility": "Universal Access",
        "tag_multi_lingual": "Multi-Lingual",
        "otp_wait_msg": "Please wait for the timer to finish before requesting again.",
        "otp_sending": "مہربانی کرتھ وؠتھو، OTP چھُ سوزنہ یوان...",
        "otp_sent_to_email": "OTP sent to your email.",
        "update_v113_title": "ڈرون فلیٹ انٹیگریشن تہٕ سیکیورٹی ہارڈننگ",
        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "یہ اپڈیٹ پلیٹ فارمچ حفاظت تہٕ آن بورڈنگ تجربہ بہتر بناونس منز مددگار ثابت گژھی:",
        "update_v113_b1": "محفوظ اکاؤنٹ حذف کرن: مینیجر پاس ورڈ تہٕ 6-ہندسوں والا OTP شٲمل متبادل تصدیق۔",
        "update_v113_b2": "OTP بہاؤچ بہتری: پورے پلیٹ فارم پؠٹھ OTP درخواستن منز گژھن وٲلہ رکاوٹ دور کرنہٕ آمٕژ۔",
        "update_v113_b3": "کردار پؠٹھ مبنی اطلاعات: رجسٹریشن، اکاؤنٹ حذف کرن تہٕ ٹریکنگ خٲطرٕ علیحدہ ای میل ٹیمپلیٹس۔",
        "update_v113_b4": "رہنمائی والا استقبالیہ تجربہ: نوؠو کمپنیوں ہیک ہن وٲنؠ پننہٕ کمالات تہٕ کمالاتک روڈ میپ سٟتؠ ای میل ملان۔",
        "update_v113_impact_desc": "اَسہِ چھُ آپریشنل تجربہ بہتر بناونہٕ خٲطرٕ تذبذب دور کورمُت:",
        "update_v113_i1": "بٔڈتھ بھروسہ: کٔشیٖر کٲم خٲطرٕ متبادل تصدیق چھِ تہاوند کمپنی ڈیٹا ہمیشہ خٲطرٕ محفوظ تھوان۔",
        "update_v113_i2": "آپریشنل وضاحت: ہر قدمس پؠٹھ رہنمائی کرن وٲلہ مواصلات۔",
        "update_v113_i3": "بے داغ تبدیلی: رجسٹریشن پؠٹھ حذف کرنس تان، UI وٲنؠ چھِ اصلی وقتک فیڈ بیک فراہم کران۔",
