        "update_v111_desc": "ଆମେ ସମଗ୍ର ମ୍ୟାନେଜର ମ୍ୟାନେଜମେଣ୍ଟ ସୁଟରେ ଗଭୀର AI ଏକୀକରଣ ପ୍ରବର୍ତ୍ତନ କରିଛୁ:",
        "update_v111_b1": "ୟୁନିଭର୍ସାଲ୍ ସ୍ମାର୍ଟ ଆସିଷ୍ଟାଣ୍ଟ ବଟନ୍: ଡ୍ରାଇଭର, ଯାନ ଏବଂ ସିପମେଣ୍ଟ ପଞ୍ଜିକରଣ ବିଭାଗରେ ସିଧାସଳଖ ସ୍ମାର୍ଟ ଆସିଷ୍ଟାଣ୍ట్ ଟ୍ରିଗରଗୁଡ଼ିକୁ ଅନ୍ତର୍ଭୁକ୍ତ କରିଛୁ |",
        "update_v111_b2": "ଗାଇଡେଡ୍ ଇଣ୍ଟରାକ୍ଟିଭ୍ ପ୍ରବାହ: ସୂଚନା ସଂଗ୍ରହ କରିବା ପାଇଁ ଚାଟବଟ୍ ବର୍ତ୍ତମାନ ଆପଣଙ୍କୁ ପର୍ଯ୍ୟାୟକ୍ରମେ ମାର୍ଗଦର୍ଶନ କରୁଛି |",
        "update_v111_b3": "ପୁନର୍ନିଧାରିତ ବଲ୍କ ଅପଲୋଡ୍ ଭିତ୍ତିଭୂମି: ସିପମେଣ୍ଟ, ଡ୍ରାଇଭର ଏବଂ ଯାନ ପାଇଁ ବଲ୍କ ଅପଲୋଡ୍ ବୈଶିଷ୍ଟ୍ୟଗୁଡ଼ିକୁ ଅପ୍ଟିମାଇଜ୍ କରିଛୁ |",
        "update_v111_b4": "ସୁରକ୍ଷା ବୁଦ୍ଧିମତା କ୍ୟାପଚର: ଇଣ୍ଟରାକ୍ଟିଭ୍ ପ୍ରବାହ ବର୍ତ୍ତମାନ ସୁରକ୍ଷା ସମ୍ବନ୍ଧୀୟ ଡ୍ରାଇଭର ମେଟ୍ରିକ୍ସକୁ ଅନ୍ତର୍ଭୁକ୍ତ କରୁଛି |",
        "update_impact_benefits": "୨) ପ୍ରଭାବ ଏବଂ ଉପଭୋକ୍ତା ଲାଭ",
        "update_v111_impact_desc": "This version focuses on making the platform more accessible and precision-oriented:",
        "update_v111_i1": "Enhanced Interactivity: Moving away from static forms makes the platform significantly more user-friendly.",
        "update_v111_i2": "Precision & Accuracy: Guided flows eliminate guesswork. Interactive dropdowns and automated formatting ensure accuracy.",
        "update_v111_i3": "Accelerated Operations: Integrated map pickers and strictly enforced dropdowns enable much faster data entry.",
        "update_v111_i4": "Verified Bulk Reliability: Redefined bulk tools ensure scaling your fleet is a smooth, error-free experience.",
        "tag_chatbot": "ଇଣ୍ଟରାକ୍ଟିଭ୍ ଚାଟବଟ୍",
        "tag_triggers": "ସ୍ମାର୍ଟ ଟ୍ରିଗର୍",
        "tag_bulk": "බଲ୍କ ଅପଲୋଡ୍ ହାର୍ଡେନିଂ",
        "tag_precision": "ପ୍ରେସିସନ୍ UX",
        "update_v101_title": "ଉନ୍ନତ ଫ୍ଲିଟ୍ ତଦାରଖ ଏବଂ ଗ୍ରାନୁଲାର୍ ଡାଟା ନିୟନ୍ତ୍ରଣ",
        "update_v101_date": "April 29, 2026 | 02:45 PM",
        "update_v101_ver": "v1.0.1 (Fleet Transparency)",
        "update_v101_desc": "ଆମେ ଗଭୀର କାର୍ଯ୍ୟକ୍ଷମ ଅନ୍ତର୍ଦୃଷ୍ଟି ଏବଂ ସୁଗମ ଡାଟା ପରିଚାଳନା ପ୍ରଦାନ କରିବାକୁ ଫ୍ଲିଟ୍ ପରିଚାଳନା ମଡ୍ୟୁଲକୁ ଯଥେଷ୍ଟ ବୃଦ୍ଧି କରିଛୁ:",
        "update_v101_b1": "ଉନ୍ନତ ଡ୍ରାଇଭର ପଞ୍ଜିକରଣ: ଡ୍ରାଇଭର ଟେବୁଲରେ ବର୍ତ୍ତମାନ ଲାଇସେନ୍ସ ପ୍ରକାର ଏବଂ ଅତୀତର ଦୁର୍ଘଟଣା ପାଇଁ ସ୍ୱତନ୍ତ୍ର ସ୍ତମ୍ଭ ଅନ୍ତର୍ଭୁକ୍ତ |",
        "update_v101_b2": "ପରିମାର୍ଜିତ ଡାଟା ପ୍ରଦର୍ଶନ: ଇଣ୍ଟରଫେସକୁ ଫୋକସ୍ ରଖିବା ପାଇଁ ଯାନ ପାସୱାର୍ଡ ପରି ଅନାବଶ୍ୟକ କ୍ଷେତ୍ରଗୁଡିକ ବାହାର କରାଯାଇଛି |",
        "update_v101_b3": "ବୁଦ୍ଧିମାନ ଇନପୁଟ୍ ନିୟନ୍ତ୍ରଣ: ଡ୍ରାଇଭର ଏବଂ ଯାନ ଉଭୟଙ୍କ ପାଇଁ ଏଡିଟ୍ ମଡ୍ୟୁଲ୍ ଅପଗ୍ରେଡ୍ କରାଯାଇଛି |",
        "update_v101_b4": "ଏକୀକୃତ ଯୋଗାଯୋଗ: ନକଲି ଫୋନ୍ ସେକ୍ସନକୁ ମିଶ୍ରଣ କରି ଡ୍ରାଇଭର ପଞ୍ଜିକରଣକୁ ସରଳ କରାଯାଇଛି |",
        "update_v101_b5": "ବ୍ୟାପକ CRUD ତଦାରଖ: ମ୍ୟାନେଜରମାନଙ୍କ ପାଖରେ ବର୍ତ୍ତମାନ ପ୍ରତ୍ୟେକ ସିଷ୍ଟମ କ୍ଷେତ୍ରକୁ ଏଡିଟ୍ କରିବାକୁ ସମ୍ପୂର୍ଣ୍ଣ କ୍ଷମତା ଅଛି |",
        "update_v101_impact_desc": "ଏହି ପରିଶୋଧନଗୁଡିକ ଆମର ମୁଖ୍ୟ ଉପଭୋକ୍ତାମାନଙ୍କ ପାଇଁ ମାପନୀୟ ଉନ୍ନତି ପ୍ରଦାନ କରେ:",
        "update_v101_i1": "ଫ୍ଲିଟ୍ ମ୍ୟାନେଜରଙ୍କ ପାଇଁ: ସମୃଦ୍ଧ ଡାଟା ଟେବୁଲ୍ ସହିତ ଦ୍ରୁତ ନିଷ୍ପତ୍ତି ଗ୍ରହଣ |",
        "update_v101_i2": "ଡାଟା ପ୍ରଶାସକଙ୍କ ପାଇଁ: ଡାଟା ଏଣ୍ଟ୍ରି ତ୍ରୁଟିରେ ବହୁତ ହ୍ରାସ |",
        "update_v101_i3": "ସପୋର୍ଟ ଟିମ୍ ପାଇଁ: ଉନ୍ନତ ସମସ୍ୟା ସମାଧାନ ଦକ୍ଷତା |",
