        "update_v112_date": "April 30, 2026 | 10:15 AM",
        "update_v112_ver": "v1.1.2 (Linguistic Parity)",
        "update_v112_title": "ବ୍ୟାପକ ବହୁ-ଭାଷା ସମର୍ଥନ ଏବଂ ସାର୍ବଭୌମିକ ପ୍ରବେଶ",
        "update_v112_desc": "ଆମେ ସମଗ୍ର ଲଜିଷ୍ଟିକ୍ସ ପ୍ଲାଟଫର୍ମରେ ପୂର୍ଣ୍ଣ ଭାଷାଗତ ସମାନତା ହାସଲ କରିଛୁ |",
        "update_v112_b1": "<strong>୧୫+ ଆଞ୍ଚଳିକ ଭାଷା:</strong> ହିନ୍ଦୀ, ବଙ୍ଗାଳୀ, ଗୁଜରାଟୀ, ତେଲୁଗୁ, ତାମିଲ, ମରାଠୀ, କନ୍ନଡ, ମାଲାୟାଲମ୍, ଓଡ଼ିଆ, ପଞ୍ଜାବୀ, ଆସାମୀ, ମୈଥିଲି, ସାନ୍ତାଳୀ ଏବଂ କାଶ୍ମୀରୀ ପାଇଁ ପୂର୍ଣ୍ଣ ସମର୍ଥନ |",
        "update_v112_b2": "<strong>ଏଣ୍ଡ-ଟୁ-ଏଣ୍ଡ ସ୍ଥାନୀୟକରଣ:</strong> ସମସ୍ତ ଡ୍ୟାସବୋର୍ଡ ଏବଂ ବଟନ୍ ସ୍ଥାନୀୟ ଭାଷାରେ ଉପଲବ୍ଧ |",
        "update_v112_b3": "<strong>ଡାଇନାମିକ ରେଜିଷ୍ଟ୍ରି ସିଙ୍କ:</strong> ପେଜ୍ ରିଲୋଡ୍ ନକରି ରିଅଲ୍-ଟାଇମ୍ UI ଅପଡେଟ୍ ନିଶ୍ଚିତ କରେ |",
        "update_v112_b4": "<strong>ସ୍ଥାନୀୟ ସହାୟତା ଏବଂ ଭଏସ୍:</strong> ସୁରକ୍ଷିତ ଡ୍ରାଇଭିଂ ପାଇଁ ଭଏସ୍ କମାଣ୍ଡ ବର୍ତ୍ତମାନ ଆଞ୍ଚଳିକ ଭାଷାରେ ଉପଲବ୍ଧ |",
        "update_v112_impact_desc": "ଅଧିକ ବ୍ୟବହାରକାରୀ ବର୍ତ୍ତମାନ ପୋର୍ଟାଲକୁ ଅଧିକ ମୁକ୍ତ ଭାବରେ ପ୍ରବେଶ କରିପାରିବେ ଏବଂ ସେମାନଙ୍କର ମାତୃଭାଷାରେ ଆତ୍ମବିଶ୍ୱାସର ସହିତ କାର୍ଯ୍ୟ କରିପାରିବେ |",
        "update_v112_i1": "ସାର୍ବଭୌମିକ ପ୍ରବେଶ: ସମସ୍ତ ଅଞ୍ଚଳର ବ୍ୟବହାରକାରୀ ବର୍ତ୍ତମାନ ସେମାନଙ୍କ ମାତୃଭାଷାରେ ପୋର୍ଟାଲ୍ ବ୍ୟବହାର କରିପାରିବେ |",
        "update_v112_i2": "କାର୍ଯ୍ୟକ୍ଷମ ଅନ୍ତର୍ଭୁକ୍ତ: ଡ୍ରାଇଭରମାନେ ବର୍ତ୍ତମାନ ସ୍ୱତନ୍ତ୍ର ଭାବରେ ନେଭିଗେଟ୍ କରିପାରିବେ ଏବଂ ସେମାନଙ୍କର ୱାଲେଟ୍ ପରିଚାଳନା କରିପାରିବେ |",
        "update_v112_i3": "ସ୍ୱଚ୍ଛତା: ସ୍ଥାନୀୟ ଆର୍ଥିକ ହେଡର୍ କାରବାରରେ ବିଶ୍ୱାସ ବଢାଇଥାଏ |",
        "update_v112_i4": "ବିଶ୍ୱସ୍ତରୀୟ ମାନକ: ବିଶ୍ୱସ୍ତରୀୟ ପ୍ରଯୁକ୍ତିବିଦ୍ୟା ସହିତ ଆଞ୍ଚଳିକ ଅନୁଭୂତିର ସମନ୍ୱୟ |",
        "tag_localization": "ସ୍ଥାନୀୟକରଣ",
        "tag_accessibility": "Universal Access",
        "tag_multi_lingual": "Multi-Lingual",
        "otp_wait_msg": "Please wait for the timer to finish before requesting again.",
        "otp_sending": "ଦୟାକରି ଅପେକ୍ଷା କରନ୍ତୁ, OTP ପଠାଯାଉଛି...",
        "otp_sent_to_email": "OTP sent to your email.",
        "update_v113_title": "ଡ୍ରୋନ୍ ଫ୍ଲିଟ୍ ଇଣ୍ଟିଗ୍ରେସନ୍ ଏବଂ ସୁରକ୍ଷା ସୁଦୃଢ଼ିକରଣ",
        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "ଏହି ଅପଡେଟ୍ ସ୍ୱୟଂଶାସିତ ଡ୍ରୋନ୍ ଫ୍ଲିଟ୍ ଗୁଡ଼ିକୁ ଏକ ପ୍ରାଥମିକ ପରିବହନ ମୋଡ୍ ଭାବରେ ପରିଚିତ କରାଏ ଏବଂ ଆକାଉଣ୍ଟ୍ ସୁରକ୍ଷାକୁ ମଜବୁତ କରେ:",
        "update_v113_b1": "ଡ୍ରୋନ୍ ଫ୍ଲିଟ୍ ପରିଚାଳନା: ଡ୍ରୋନ୍ ଗୁଡ଼ିକ ବର୍ତ୍ତମାନ ପଞ୍ଜିକରଣ, ଲାଇସେନ୍ସ ଟ୍ରାକିଂ ଏବଂ ବଲ୍କ ଅପଲୋଡ୍ ସମର୍ଥନ ସହିତ ଏକ ମୁଖ୍ୟ ପରିବହନ ମୋଡ୍ |",
        "update_v113_b2": "ସ୍ମାର୍ଟ ଡ୍ରୋନ୍ ସହାୟକ: ନିର୍ଦ୍ଦେଶିତ ପଦକ୍ଷେପ ଅନୁଯାୟୀ ଚାଟ୍ ଇଣ୍ଟରଫେସ୍ ମାଧ୍ୟମରେ ଡ୍ରୋନ୍ ଗୁଡ଼ିକୁ ଅନବୋର୍ଡ କରନ୍ତୁ |",
        "update_v113_b3": "ଉନ୍ନତ OTP ବିଶ୍ୱସନୀୟତା: ସାଇନ୍ ଅପ୍, ଆକାଉଣ୍ଟ୍ ବିଲୋପ ଏବଂ ଟ୍ରାକିଂ ପ୍ରବାହରେ OTP ଅନୁରୋଧରେ ସିଷ୍ଟମ୍ ହ୍ୟାଙ୍ଗିଙ୍ଗ୍ ସମସ୍ୟାର ସମାଧାନ ହୋଇଛି |",
        "update_v113_b4": "ସୁରକ୍ଷିତ ଆକାଉଣ୍ଟ୍ ବିଲୋପ: ସର୍ବାଧିକ ସୁରକ୍ଷା ପାଇଁ ଆକାଉଣ୍ଟ୍ ହଟାଇବା ପାଇଁ ବର୍ତ୍ତମାନ ମ୍ୟାନେଜର୍ ପାସୱାର୍ଡ ଏବଂ OTP ସହିତ ମଲ୍ଟି-ଫ୍ୟାକ୍ଟର୍ ଯାଞ୍ଚ ଆବଶ୍ୟକ |",
        "update_v113_impact_desc": "ବ୍ୟବହାରକାରୀମାନେ ଅଧିକ ବହୁମୁଖୀ ଫ୍ଲିଟ୍ ଏବଂ ଅଧିକ ନିର୍ଭରଯୋଗ୍ୟ ପ୍ରାମାଣିକିକରଣ ଅଭିଜ୍ଞତାରୁ ଉପକୃତ ହେବେ:",
        "update_v113_i1": "ବହୁମୁଖୀ ଲଜିଷ୍ଟିକ୍ସ: ଏକୀକୃତ 'Drivers & Fleet' ଡ୍ୟାସବୋର୍ଡରୁ ଉଭୟ ସ୍ଥଳ ଏବଂ ଆକାଶ ମାର୍ଗର ସମ୍ପତ୍ତିକୁ ନିରନ୍ତର ପରିଚାଳନା କରନ୍ତୁ |",
        "update_v113_i2": "ସହଜ ଅନବୋର୍ଡିଂ: ସ୍ମାର୍ଟ ସହାୟକମାନେ ଆପଣଙ୍କୁ ଜଟିଳ ପଞ୍ଜିକରଣ ମାଧ୍ୟମରେ ମାର୍ଗଦର୍ଶନ କରନ୍ତି, ଯାହା ଡେଟା ଏଣ୍ଟ୍ରି ତ୍ରୁଟିକୁ ଦୂର କରେ |",
        "update_v113_i3": "ନିର୍ଭରଯୋଗ୍ୟ ପ୍ରାମାଣିକିକରଣ: ସ୍ଥାନୀୟ OTP ବାର୍ତ୍ତା ଏବଂ ଉନ୍ନତ ବ୍ୟାକେଣ୍ଡ ସିଙ୍କ୍ରୋନାଇଜେସନ୍ ନିଶ୍ଚିତ କରେ ଯେ ଆପଣ ଯାଞ୍ଚ ସମୟରେ କଦାପି ଅଟକିବେ ନାହିଁ |",
