        "update_v111_title": "युनिफाइड स्मार्ट असिस्टंट ट्रिगर्स आणि बल्क डेटा हार्डनिंग",
        "update_v111_date": "April 29, 2026 | 09:00 PM",
        "update_v111_ver": "v1.1.1 (Smart Assistant)",
        "update_actual_updates": "1) प्रत्यक्ष अपडेट्स",
        "update_v111_desc": "आम्ही संपूर्ण व्यवस्थापक व्यवस्थापन सूटमध्ये खोलवर AI एकत्रीकरण सादर केले आहे:",
        "update_v111_b1": "युनिव्हर्सल स्मार्ट असिस्टंट बटणे: ड्रायव्हर, वाहन आणि शिपमेंट नोंदणी विभागांमध्ये थेट स्मार्ट असिस्टंट ट्रिगर्स एकत्रित केले आहेत.",
        "update_v111_b2": "मार्गदर्शित परस्परसंवादी प्रवाह: चॅटबॉट आता माहिती गोळा करण्यासाठी तुम्हाला चरण-दर-चरण संवादामधून घेऊन जातो.",
        "update_v111_b3": "पुनर्परिभाषित बल्क अपलोड पायाभूत सुविधा: शिपमेंट, ड्रायव्हर्स आणि वाहनांसाठी बल्क अपलोड वैशिष्ट्ये ऑप्टिमाइझ केली आहेत.",
        "update_v111_b4": "सुरक्षा बुद्धिमत्ता कॅप्चर: परस्परसंवादी प्रवाहामध्ये आता सुरक्षा-गंभीर ड्रायव्हर मेट्रिक्स समाविष्ट आहेत.",
        "update_impact_benefits": "2) प्रभाव आणि वापरकर्ता फायदे",
        "update_v111_impact_desc": "ही आवृत्ती प्लॅटफॉर्म अधिक सुलभ आणि अचूक बनवण्यावर लक्ष केंद्रित करते:",
        "update_v111_i1": "वर्धित परस्परसंवाद: स्थिर फॉर्मपासून दूर जाणे प्लॅटफॉर्म वापरकर्त्यांसाठी अधिक अनुकूल बनवते.",
        "update_v111_i2": "अचूकता: मार्गदर्शित प्रवाह अंदाज काढून टाकतात. परस्परसंवादी ड्रॉपडाउन अचूकता सुनिश्चित करतात.",
        "update_v111_i3": "वेगवान ऑपरेशन्स: एकात्मिक नकाशे आणि ड्रॉपडाउन अधिक जलद डेटा एंट्री सक्षम करतात.",
        "update_v111_i4": "सत्यापित बल्क विश्वसनीयता: पुनर्परिभाषित बल्क टूल्स तुमचे फ्लीट वाढवणे सोपे करतात.",
