        "update_v112_date": "April 30, 2026 | 10:15 AM",
        "update_v112_ver": "v1.1.2 (Linguistic Parity)",
        "update_v112_title": "सर्वसमावेशक बहु-भाषा समर्थन आणि सार्वत्रिक सुलभता",
        "update_v112_desc": "आम्ही संपूर्ण लॉजिस्टिक प्लॅटफॉर्मवर पूर्ण भाषिक समानता प्राप्त केली आहे. व्यवस्थापक, चालक आणि ग्राहक आता त्यांच्या मूळ प्रादेशिक भाषांमध्ये पोर्टलशी संवाद साधू शकतात.",
        "update_v112_b1": "<strong>15+ प्रादेशिक भाषा:</strong> हिंदी, बंगाली, गुजराती, तेलगू, तमिळ, मराठी, कन्नड, मल्याळम, उडिया, पंजाबी, आसामी, मैथिली, संताली आणि काश्मीरीसाठी पूर्ण समर्थन जोडले.",
        "update_v112_b2": "<strong>एंड-टू-एंड स्थानिकीकरण:</strong> प्रत्येक डॅशबोर्ड, टेबल हेडर, बटण आणि सिस्टम सूचना स्थानिकीकृत केल्या आहेत.",
        "update_v112_b3": "<strong>डायनॅमिक रजिस्ट्री सिंक:</strong> पेज रीलोडशिवाय रिअल-टाइम UI अपडेट सुनिश्चित करणारे केंद्रीकृत भाषांतर इंजिन.",
        "update_v112_b4": "<strong>स्थानिकीकृत मदत आणि आवाज:</strong> सुरक्षित ड्रायव्हर ऑपरेशन्ससाठी आता व्हॉइस कमांड्स प्रादेशिक भाषांमध्ये उपलब्ध आहेत.",
        "update_v112_impact_desc": "हे अपडेट भाषिक अडथळे दूर करते, ज्यामुळे व्यावसायिक लॉजिस्टिक व्यवस्थापन सर्वांसाठी सुलभ होते:",
        "update_v112_i1": "सार्वत्रिक प्रवेश: सर्व प्रदेशातील वापरकर्ते आता पोर्टलवर अधिक मुक्तपणे आणि त्यांच्या मातृभाषेत आत्मविश्वासाने प्रवेश करू शकतात.",
        "update_v112_i2": "परिचालन समावेश: ड्रायव्हर्स आता स्वतंत्रपणे नेव्हिगेट करू शकतात आणि त्यांचे वॉलेट व्यवस्थापित करू शकतात.",
        "update_v112_i3": "कमी घर्षण: स्थानिकीकृत आर्थिक हेडर व्यवहारांमध्ये पारदर्शकता आणि विश्वास सुनिश्चित करतात.",
        "update_v112_i4": "जागतिक मानके, स्थानिक अनुभव: जागतिक दर्जाचे तंत्रज्ञान आणि प्रादेशिक अनुभवाचा संगम.",
        "tag_localization": "स्थानिकीकरण",
        "tag_accessibility": "Universal Access",
        "tag_multi_lingual": "Multi-Lingual",
        "otp_wait_msg": "Please wait for the timer to finish before requesting again.",
        "otp_sending": "कृपया प्रतीक्षा करा, ओटीपी पाठवला जात आहे...",
        "otp_sent_to_email": "OTP sent to your email.",
        "update_v113_title": "ड्रोन फ्लीट एकत्रीकरण आणि सुरक्षा सुदृढीकरण",
        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "हे अपडेट स्वायत्त ड्रोन ताफ्याचा प्राथमिक वाहतूक मोड म्हणून परिचय करून देते आणि खाते सुरक्षा मजबूत करते:",
        "update_v113_b1": "ड्रोन फ्लीट व्यवस्थापन: ड्रोन आता वाहतुकीचा एक प्रमुख प्रकार आहे, समर्पित नोंदणी, परवाना ट्रॅकिंग आणि बल्क अपलोड समर्थनासह.",
        "update_v113_b2": "स्मार्ट ड्रोन सहाय्यक: मार्गदर्शित स्टेप-बाय-स्टेप चॅट इंटरफेसद्वारे ड्रोन ऑनबोर्ड करा.",
        "update_v113_b3": "सुधारित ओटीपी विश्वसनीयता: साइनअप, खाते हटवणे आणि ট্র্যাকিং फ्लोमधील ओटीपी विनंत्यांमधील समस्यांचे निराकरण केले.",
        "update_v113_b4": "सुरक्षित विलोपन वर्कफ्लो: खाते हटवण्यासाठी आता जास्तीत जास्त सुरक्षेसाठी मल्टी-फॅक्टर ऑथेंटिकेशन आवश्यक आहे.",
        "update_v113_impact_desc": "वापरकर्त्यांना अधिक बहुमुखी फ्लीट आणि अधिक विश्वासार्ह प्रमाणीकरण अनुभवाचा फायदा होईल:",
        "update_v113_i1": "बहुमुखी लॉजिस्टिक्स: एकात्मिक 'Drivers & Fleet' डॅशबोर्डवरून स्थलीय आणि हवाई दोन्ही मालमत्तांचे अखंडपणे व्यवस्थापन करा.",
        "update_v113_i2": "सहज ऑनबोर्डिंग: स्मार्ट सहाय्यक तुम्हाला क्लिष्ट नोंदणीद्वारे मार्गदर्शन करतात, डेटा एंट्री त्रुटी दूर करतात.",
        "update_v113_i3": "विश्वासार्హ प्रमाणीकरण: स्थानिक ओटीपी संदेश आणि सुधारित बॅकएंड सिंक्रोनाइझेशन सुनिश्चित करतात की तुम्ही पडताळणी दरम्यान कधीही अडकणार नाही.",
