        "update_v112_date": "April 30, 2026 | 10:15 AM",
        "update_v112_ver": "v1.1.2 (Linguistic Parity)",
        "update_v112_title": "বিস্তৃত বহু-ভাষা সমর্থন এবং সার্বজনীন অ্যাক্সেস",
        "update_v112_desc": "আমরা পুরো লজিস্টিক প্ল্যাটফর্মে পূর্ণ ভাষাগত সামঞ্জস্য অর্জন করেছি। ম্যানেজার, ড্রাইভার এবং গ্রাহকরা এখন তাদের আঞ্চলিক ভাষায় পোর্টালের সাথে যোগাযোগ করতে পারেন।",
        "update_v112_b1": "<strong>১৫+ আঞ্চলিক ভাষা:</strong> হিন্দি, বাংলা, গুজরাটি, তেলুগু, তামিল, মারাঠি, কন্নড়, মালায়ালম, ওড়িয়া, পাঞ্জাবি, অসমীয়া, মৈথিলী, সাঁওতালি এবং কাশ্মীরির জন্য পূর্ণ সমর্থন যোগ করা হয়েছে।",
        "update_v112_b2": "<strong>এন্ড-টু-এন্ড স্থানীয়করণ:</strong> প্রতিটি ড্যাশবোর্ড, টেবিল হেডার, বোতাম এবং সিস্টেম নোটিফিকেশন স্থানীয়করণ করা হয়েছে।",
        "update_v112_b3": "<strong>ডায়নামিক রেজিস্ট্রি সিঙ্ক:</strong> একটি কেন্দ্রীভূত অনুবাদ ইঞ্জিন চালু করা হয়েছে যা পৃষ্ঠা রিলোড ছাড়াই রিয়েল-টাইম ইউআই আপডেট নিশ্চিত করে।",
        "update_v112_b4": "<strong>স্থানীয় সাহায্য এবং ভয়েস:</strong> নিরাপদ ড্রাইভার অপারেশনের জন্য সমস্ত সমর্থিত আঞ্চলিক উপভাষায় হ্যান্ডস-ফ্রি ভয়েস কমান্ড এবং সহায়তা গাইড এখন উপলব্ধ।",
        "update_v112_impact_desc": "এই আপডেট ভাষাগত বাধা দূর করে পেশাদার লজিস্টিক ম্যানেজমেন্টকে সবার কাছে অ্যাক্সেসযোগ্য করে তোলে:",
        "update_v112_i1": "সার্বজনীন অ্যাক্সেস: ভারতের সব অঞ্চলের ব্যবহারকারীরা এখন তাদের মাতৃভাষায় পোর্টালটি আরও অবাধে অ্যাক্সেস করতে পারেন।",
        "update_v112_i2": "অপারেশনাল অন্তর্ভুক্তি: ড্রাইভাররা যারা আগে শুধুমাত্র ইংরেজি ইন্টারফেসে সীমাবদ্ধ ছিলেন তারা এখন স্বাধীনভাবে নেভিগেট করতে পারেন।",
        "update_v112_i3": "ঘর্ষণ হ্রাস: স্থানীয় আর্থিক হেডার এবং স্মার্ট চুক্তির শর্তাবলী বহু-পক্ষীয় লেনদেনে স্বচ্ছতা নিশ্চিত করে।",
        "update_v112_i4": "বৈশ্বিক মান, স্থানীয় অনুভূতি: বিশ্বমানের প্রযুক্তির সাথে আঞ্চলিক অভিজ্ঞতাকে একত্রিত করে।",
        "tag_localization": "Localization",
        "tag_accessibility": "Universal Access",
        "tag_multi_lingual": "Multi-Lingual",
        "otp_wait_msg": "Please wait for the timer to finish before requesting again.",
        "otp_sending": "দয়া করে অপেক্ষা করুন, ওটিপি পাঠানো হচ্ছে...",
        "otp_sent_to_email": "আপনার ইমেলে OTP পাঠানো হয়েছে।",
        "update_v113_title": "ড্রোন ফ্লিট ইন্টিগ্রেশন এবং নিরাপত্তা শক্তিশালীকরণ",
        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "এই আপডেট পরিবহনের প্রাথমিক মোড হিসাবে স্বায়ত্তশাসিত ড্রোন ফ্লিট প্রবর্তন করে এবং অ্যাকাউন্ট নিরাপত্তা আরও উন্নত করে:",
        "update_v113_b1": "ড্রোন ফ্লিট ম্যানেজমেন্ট: ড্রোন এখন পরিবহনের একটি প্রধান মাধ্যম, যার জন্য রয়েছে ডেডিকেটেড রেজিস্ট্রেশন, লাইসেন্স ট্র্যাকিং এবং বাল্ক আপলোড সুবিধা।",
        "update_v113_b2": "স্মার্ট ড্রোন অ্যাসিস্ট্যান্ট: নির্দেশিত ধাপে ধাপে চ্যাট ইন্টারফেসের মাধ্যমে ড্রোন অনবোর্ড করুন।",
        "update_v113_b3": "উন্নত ওটিপি নির্ভরযোগ্যতা: সাইনআপ, অ্যাকাউন্ট মুছে ফেলা এবং ট্র্যাকিং ফ্লোতে ওটিপি অনুরোধের সমস্যাগুলো সমাধান করা হয়েছে।",
        "update_v113_b4": "নিরাপদ অ্যাকাউন্ট ডিলিট প্রক্রিয়া: সর্বোচ্চ নিরাপত্তার জন্য অ্যাকাউন্ট মুছে ফেলার ক্ষেত্রে এখন মাল্টি-ফ্যাক্টর অথেন্টিকেশন প্রয়োজন।",
        "update_v113_impact_desc": "ব্যবহারকারীরা একটি বহুমুখী ফ্লিট এবং আরও নির্ভরযোগ্য প্রমাণীকরণ অভিজ্ঞতা থেকে উপকৃত হবেন:",
        "update_v113_i1": "বহুমুখী লজিস্টিকস: একটি সমন্বিত 'Drivers & Fleet' ড্যাশবোর্ড থেকে স্থলজ এবং আকাশপথের সম্পদ নির্বিঘ্নে পরিচালনা করুন।",
        "update_v113_i2": "সহজ অনবোর্ডিং: স্মার্ট অ্যাসিস্ট্যান্টরা আপনাকে জটিল রেজিস্ট্রেশনের মাধ্যমে গাইড করবে, যা ডেটা এন্ট্রি ত্রুটি দূর করবে।",
        "update_v113_i3": "নির্ভরযোগ্য প্রমাণীকরণ: স্থানীয় ওটিপি বার্তা এবং উন্নত ব্যাকএন্ড সিঙ্ক্রোনাইজেশন নিশ্চিত করে যে আপনি যাচাইকরণের সময় কখনই আটকে যাবেন না।",
