        "update_v112_date": "April 30, 2026 | 10:15 AM",
        "update_v112_ver": "v1.1.2 (Linguistic Parity)",
        "update_v112_title": "விரிவான பல மொழி ஆதரவு மற்றும் உலகளாவிய அணுகல்",
        "update_v112_desc": "We have achieved full linguistic parity across the entire Logistix platform. Managers, drivers, and customers can now interact with the portal in their native regional languages.",
        "update_v112_b1": "<strong>15+ பிராந்திய மொழிகள்:</strong> இந்தி, பெங்காலி, குஜராத்தி, தெலுங்கு, தமிழ், மராத்தி, கன்னடம், மலையாளம், ஒடியா, பஞ்சாபி, அஸ்ஸாமி, மைதிலி, சந்தாலி மற்றும் காஷ்மீரி மொழிகளுக்கு முழு ஆதரவு சேர்க்கப்பட்டுள்ளது.",
        "update_v112_b2": "<strong>எண்ட்-டு-எண்ட் உள்ளூர்மயமாக்கல்:</strong> ஒவ்வொரு டாஷ்போர்டு, டேபிள் ஹெடர், பட்டன் மற்றும் கணினி அறிவிப்பு உள்ளூர்மயமாக்கப்பட்டுள்ளன.",
        "update_v112_b3": "<strong>டைனமிக் ரெஜிஸ்ட்ரி ஒத்திசைவு:</strong> பக்கத்தை மீண்டும் ஏற்றாமல் நிகழ்நேர UI புதுப்பிப்புகளை உறுதி செய்யும் ஒரு மையப்படுத்தப்பட்ட மொழிபெயர்ப்பு இயந்திரம்.",
        "update_v112_b4": "<strong>உள்ளூர்மயமாக்கப்பட்ட உதவி மற்றும் குரல்:</strong> பாதுகாப்பான ஓட்டுநர் செயல்பாடுகளுக்காக குரல் கட்டளைகள் இப்போது பிராந்திய மொழிகளில் கிடைக்கின்றன.",
        "update_v112_impact_desc": "அதிகப்படியான பயனர்கள் இப்போது போர்ட்டலை மிகவும் சுதந்திரமாக அணுகலாம் மற்றும் அவர்களின் தாய்மொழியில் நம்பிக்கையுடன் செயல்படலாம்.",
        "update_v112_i1": "உலகளாவிய அணுகல்: இந்தியாவின் அனைத்துப் பகுதிகளையும் சேர்ந்த பயனர்கள் இப்போது தங்கள் தாய்மொழியில் போர்ட்டலை மிகவும் சுதந்திரமாக அணுகலாம்.",
        "update_v112_i2": "செயல்பாட்டு உள்ளடக்கம்: ஓட்டுநர்கள் இப்போது சுதந்திரமாக செல்லவும் தங்கள் பணப்பையை நிர்வகிக்கவும் முடியும்.",
        "update_v112_i3": "குறைக்கப்பட்ட சிரமங்கள்: உள்ளூர்மயமாக்கப்பட்ட நிதி தலைப்புகள் பரிவர்த்தனைகளில் வெளிப்படைத்தன்மையை உறுதி செய்கின்றன.",
        "update_v112_i4": "உலகளாவிய தரநிலைகள், உள்ளூர் உணர்வு: உலகத் தரம் வாய்ந்த தொழில்நுட்பத்தை பிராந்திய அனுபவத்துடன் இணைக்கிறது.",
        "tag_localization": "உள்ளூர்மயமாக்கல்",
        "tag_accessibility": "Universal Access",
        "tag_multi_lingual": "Multi-Lingual",
        "otp_wait_msg": "Please wait for the timer to finish before requesting again.",
        "otp_sending": "தயவுசெய்து காத்திருக்கவும், OTP அனுப்பப்படுகிறது...",
        "otp_sent_to_email": "OTP sent to your email.",
        "update_v113_title": "ட்ரோன் கடற்படை ஒருங்கிணைப்பு & பாதுகாப்பு வலுப்படுத்துதல்",
        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "இந்த அப்டேட் தன்னாட்சி ட்ரோன் கடற்படைகளை முதன்மை போக்குவரத்து முறையாக அறிமுகப்படுத்துகிறது మరియు கணக்கு பாதுகாப்பை பலப்படுத்துகிறது:",
        "update_v113_b1": "ட்ரோன் கடற்படை மேலாண்மை: ட்ரோன்கள் இப்போது ஒரு முக்கிய போக்குவரத்து முறையாகும், பிரத்யேக பதிவு, உரிம கண்காணிப்பு మరియు மொத்த பதிவேற்ற ஆதரவுடன்.",
        "update_v113_b2": "ஸ்మార్ట్ ட்ரோன் உதவியாளர்: வழிகாட்டப்பட்ட படிப்படியான அரட்டை இடைமுகம் மூலம் ட்ரோன்களை இணைக்கவும்.",
        "update_v113_b3": "மேம்படுத்தப்பட்ட OTP நம்பகத்தன்மை: பதிவுசெய்தல், கணக்கு நீக்கம் மற்றும் கண்காணிப்பு ஓட்டங்களில் OTP கோரிக்கைகளில் உள்ள சிக்கல்கள் சரிசெய்யப்பட்டன.",
        "update_v113_b4": "பாதுகாப்பான நீக்குதல் பணிப்பாய்வு: அதிகபட்ச பாதுகாப்பிற்காக கணக்கு நீக்கத்திற்கு இப்போது மல்டி-பேக்டர் அங்கீகாரம் தேவை.",
        "update_v113_impact_desc": "பயனர்கள் மிகவும் பல்துறை கடற்படை மற்றும் நம்பகமான அங்கீகார அனுபவத்திலிருந்து பயனடைவார்கள்:",
        "update_v113_i1": "பல்துறை லாஜிஸ்டிக்ஸ்: ஒருங்கிணைந்த 'Drivers & Fleet' டாஷ்போர்டிலிருந்து நிலப்பரப்பு మరియు வான்வழி சொத்துக்களை தடையின்றி నిர்வகிக்கவும்.",
        "update_v113_i2": "சிரமமில்லாத ஆன்போர்டிங்: ஸ்மார்ட் உதவியாளர்கள் சிக்கலான பதிவுகள் மூலம் உங்களுக்கு வழிகாட்டுவார்கள், தரவு நுழைவு பிழைகளை நீக்குவார்கள்.",
        "update_v113_i3": "நம்பகமான அங்கீகாரம்: உள்ளூர்மயமாக்கப்பட்ட OTP செய்திகள் மற்றும் மேம்படுத்தப்பட்ட பேக்எண்ட் ஒத்திசைவு சரிபார்ப்பின் போது நீங்கள் ஒருபோதும் சிக்கிக்கொள்ளாமல் இருப்பதை உறுதி செய்கிறது.",
