        "update_v112_date": "April 30, 2026 | 10:15 AM",
        "update_v112_ver": "v1.1.2 (Linguistic Parity)",
        "update_v112_title": "സമഗ്രമായ ബഹുഭാഷാ പിന്തുണയും സാർവത്രിക പ്രവേശനക്ഷമതയും",
        "update_v112_desc": "മുഴുവൻ ലോജിസ്റ്റിക് പ്ലാറ്റ്‌ഫോമിലും ഞങ്ങൾ പൂർണ്ണ ഭാഷാപരമായ സമത്വം കൈവരിച്ചു.",
        "update_v112_b1": "<strong>15+ പ്രാദേശിക ഭാഷകൾ:</strong> ഹിന്ദി, ബംഗാളി, ഗുജറാത്തി, തെലുങ്ക്, തമിഴ്, മറാത്തി, കന്നഡ, മലയാളം, ഒഡിയ, പഞ്ചാബി, ആസാമീസ്, മൈഥിലി, സന്താലി, കശ്മീരി എന്നിവയ്ക്ക് പൂർണ്ണ പിന്തുണ.",
        "update_v112_b2": "<strong>എൻഡ്-ടു-എൻഡ് പ്രാദേശികവൽക്കരണം:</strong> എല്ലാ ഡാഷ്‌ബോർഡുകളും ബട്ടണുകളും പ്രാദേശിക ഭാഷയിലേക്ക് മാറ്റി.",
        "update_v112_b3": "<strong>ഡൈനാമിക് രജിസ്ട്രി സിങ്ക്:</strong> പേജ് റീലോഡ് ചെയ്യാതെ തന്നെ തത്സമയ UI അപ്‌ഡേറ്റുകൾ ഉറപ്പാക്കുന്നു.",
        "update_v112_b4": "<strong>പ്രാദേശിക സഹായവും ശബ്ദവും:</strong> സുരക്ഷിതമായ ഡ്രൈവിംഗിനായി വോയ്‌സ് കമാൻഡുകൾ ഇപ്പോൾ പ്രാദേശിക ഭാഷകളിൽ ലഭ്യമാണ്.",
        "update_v112_impact_desc": "കൂടുതൽ ഉപയോക്താക്കൾക്ക് ഇപ്പോൾ പോർട്ടൽ കൂടുതൽ സ്വതന്ത്രമായി ആക്സസ് ചെയ്യാനും അവരുടെ മാതൃഭാഷയിൽ ആത്മവിശ്വാസത്തോടെ പ്രവർത്തിക്കാനും കഴിയും.",
        "update_v112_i1": "സാർവത്രിക പ്രവേശനം: എല്ലാ പ്രദേശങ്ങളിലുമുള്ള ഉപയോക്താക്കൾക്ക് ഇപ്പോൾ അവരുടെ മാതൃഭാഷയിൽ പോർട്ടൽ ആക്സസ് ചെയ്യാം.",
        "update_v112_i2": "പ്രവർത്തനപരമായ ഉൾപ്പെടുത്തൽ: ഡ്രൈവർമാർക്ക് ഇപ്പോൾ സ്വതന്ത്രമായി നാവിഗേറ്റ് ചെയ്യാനും അവരുടെ വാലറ്റ് കൈകാര്യം ചെയ്യാനും കഴിയും.",
        "update_v112_i3": "തടസ്സമില്ലാത്ത ഇടപാടുകൾ: പ്രാദേശിക സാമ്പത്തിക ഹെഡറുകൾ സുതാര്യതയും വിശ്വാസവും ഉറപ്പാക്കുന്നു.",
        "update_v112_i4": "ആഗോള നിലവാരം, പ്രാദേശിക അനുഭവം: ലോകോത്തര സാങ്കേതികവിദ്യയും പ്രാദേശിക അനുഭവവും സംയോജിപ്പിക്കുന്നു.",
        "tag_localization": "പ്രാദേശികവൽക്കരണം",
        "tag_accessibility": "Universal Access",
        "tag_multi_lingual": "Multi-Lingual",
        "otp_wait_msg": "Please wait for the timer to finish before requesting again.",
        "otp_sending": "ദയവായി കാത്തിരിക്കുക, OTP അയക്കുന്നു...",
        "otp_sent_to_email": "OTP sent to your email.",
        "update_v113_title": "ഡ്രോൺ ഫ്ലീറ്റ് സംയോജനവും സുരക്ഷാ വർദ്ധനയും",
        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "ഈ അപ്‌ഡേറ്റ് സ്വയംഭരണ ഡ്രോൺ ഫ്ലീറ്റുകളെ പ്രാഥമിക ഗതാഗത മോഡായി അവതരിപ്പിക്കുകയും അക്കൗണ്ട് സുരക്ഷ ശക്തിപ്പെടുത്തുകയും ചെയ്യുന്നു:",
        "update_v113_b1": "ഡ്രോൺ ഫ്ലീറ്റ് മാനേജ്‌മെന്റ്: സമർപ്പിത രജിസ്ട്രേഷൻ, ലൈസൻസ് ട്രാക്കിംഗ്, ബൾക്ക് അപ്‌ലോഡ് പിന്തുണ എന്നിവയുള്ള ഡ്രോണുകൾ ഇപ്പോൾ ഒരു പ്രൈമറി ട്രാൻസ്‌പോർട്ടേഷൻ മോഡാണ്.",
        "update_v113_b2": "സ്മാർട്ട് ഡ്രോൺ അസിസ്റ്റന്റ്: ഗൈഡഡ് സ്റ്റെപ്പ്-ബൈ-സ്റ്റെപ് ചാറ്റ് ഇന്റർഫേസിലൂടെ ഡ്രോണുകളെ ഓൺബോർഡ് ചെയ്യുക.",
        "update_v113_b3": "മെച്ചപ്പെട്ട OTP വിശ്വാസ്യത: സൈൻഅപ്പ്, അക്കൗണ്ട് ഇല്ലാതാക്കൽ, ട്രാക്കിംഗ് ഫ്ലോകൾ എന്നിവയിലുടനീളമുള്ള OTP അഭ്യർത്ഥനകളിലെ പ്രശ്നങ്ങൾ പരിഹരിച്ചു.",
        "update_v113_b4": "സുരക്ഷിത അക്കൗണ്ട് ഇല്ലാതാക്കൽ: പരമാവധി സുരക്ഷയ്ക്കായി അക്കൗണ്ട് നീക്കം ചെയ്യുന്നതിന് ഇപ്പോൾ മാനേജർ പാസ്‌വേഡും OTP-യും ഉള്ള മൾട്ടി-ഫാക്ടർ വെരിഫിക്കേഷൻ ആവശ്യമാണ്.",
        "update_v113_impact_desc": "ഉപയോക്താക്കൾക്ക് കൂടുതൽ ബഹുമുഖമായ ഫ്ലീറ്റും കൂടുതൽ വിശ്വസനീയമായ ഓതന്റിക്കേഷൻ അനുഭവവും ലഭിക്കും:",
        "update_v113_i1": "ബഹുമുഖ ലോജിസ്റ്റിക്സ്: ഏകീകൃതമായ 'Drivers & Fleet' ഡാഷ്‌ബോർഡിൽ നിന്ന് കര, വ്യോമ ആസ്തികൾ തടസ്സമില്ലാതെ മാനേജ് ചെയ്യുക.",
        "update_v113_i2": "അനായാസമായ ഓൺബോർഡിംഗ്: സങ്കീർണ്ണമായ രജിസ്ട്രേഷനുകളിലൂടെ സ്മാർട്ട് അസിസ്റ്റന്റുകൾ നിങ്ങളെ നയിക്കുന്നു, ഡാറ്റാ എൻട്രി പിശകുകൾ ഇല്ലാതാക്കുന്നു.",
        "update_v113_i3": "വിശ്വസനീയമായ ഓതന്റിക്കേഷൻ: പ്രാദേശികവൽക്കരിച്ച OTP സന്ദേശങ്ങളും മെച്ചപ്പെട്ട ബാക്കെൻഡ് സിൻക്രൊണൈസേഷനും പരിശോധനയ്ക്കിടയിൽ നിങ്ങൾ ഒരിക്കലും കുടുങ്ങിപ്പോകില്ലെന്ന് ഉറപ്പാക്കുന്നു.",
