        "update_v111_title": "ਯੂਨੀਫਾਈਡ ਸਮਾਰట్ ਅਸਿਸਟੈਂਟ ਟ੍ਰਿਗਰਜ਼ ਅਤੇ ਬਲਕ ਡੇਟਾ ਹਾਰਡਨਿੰગ",
        "update_v111_date": "April 29, 2026 | 09:00 PM",
        "update_v111_ver": "v1.1.1 (Smart Assistant)",
        "update_actual_updates": "1) ਮੁੱਖ ਅੱਪਡੇਟ",
        "update_v111_desc": "ਅਸੀਂ ਪੂਰੇ ਮੈਨੇਜਰ ਪ੍ਰਬੰਧਨ ਸੂਟ ਵਿੱਚ ਡੂੰਘੀ AI ਏਕੀਕਰਣ ਪੇਸ਼ ਕੀਤੀ ਹੈ:",
        "update_v111_b1": "ਯੂਨੀਵਰਸਲ ਸਮਾਰట్ ਅਸਿਸਟੈਂਟ ਬਟਨ: ਡਰਾਈਵਰ, ਵਾਹਨ ਅਤੇ ਸ਼ਿਪਮੈਂਟ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸੈਕਸ਼ਨਾਂ ਵਿੱਚ ਸਿੱਧੇ ਸਮਾਰట్ ਅਸਿਸਟੈਂట్ ਟ੍ਰਿਗਰਸ ਸ਼ਾਮਲ ਕੀਤੇ ਗਏ ਹਨ।",
        "update_v111_b2": "ਗਾਈਡਡ ਇੰਟਰਐਕਟਿవ్ ਫਲੋ: ਚੈਟਬੋਟ ਹੁਣ ਜਾਣਕਾਰੀ ਇਕੱਠੀ ਕਰਨ ਲਈ ਤੁਹਾਨੂੰ ਕਦਮ-ਦਰ-ਕਦਮ ਸੰਵਾਦ ਰਾਹੀਂ ਲੈ ਜਾਂਦਾ ਹੈ।",
        "update_v111_b3": "ਮੁੜ-ਪਰਿਭਾਸ਼ਿਤ ਬਲਕ ਅੱਪਲੋਡ ਬੁਨਿਆਦੀ ਢਾਂਚਾ: ਸ਼ਿਪਮੈਂਟਾਂ, ਡਰਾਈਵਰਾਂ ਅਤੇ ਵਾਹਨਾਂ ਲਈ ਬਲਕ ਅੱਪਲੋਡ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨੂੰ ਅਨੁਕੂਲ ਬਣਾਇਆ ਗਿਆ ਹੈ।",
        "update_v111_b4": "ਸੁਰੱਖਿਆ ਇੰਟੈਲੀਜੈਂਸ ਕੈਪਚਰ: ਇੰਟਰਐਕਟਿవ్ ਫਲੋ ਹੁਣ ਸੁਰੱਖਿਆ-ਨਾਜ਼ੁਕ ਡਰਾਈవర్ ਮੈਟ੍ਰਿਕਸ ਨੂੰ ਸਹਿਜੇ ਹੀ ਸ਼ਾਮਲ ਕਰਦਾ ਹੈ।",
        "update_impact_benefits": "2) ਪ੍ਰਭਾਵ ਅਤੇ ਉਪਭੋਗਤਾ ਲਾਭ",
        "update_v111_impact_desc": "This version focuses on making the platform more accessible and precision-oriented:",
        "update_v111_i1": "Enhanced Interactivity: Moving away from static forms makes the platform significantly more user-friendly.",
        "update_v111_i2": "Precision & Accuracy: Guided flows eliminate guesswork. Interactive dropdowns and automated formatting ensure accuracy.",
        "update_v111_i3": "Accelerated Operations: Integrated map pickers and strictly enforced dropdowns enable much faster data entry.",
        "update_v111_i4": "Verified Bulk Reliability: Redefined bulk tools ensure scaling your fleet is a smooth, error-free experience.",
        "tag_chatbot": "ਇੰਟਰਐਕਟਿవ్ ਚੈਟਬੋਟ",
        "tag_triggers": "ਸਮਾਰਟ ਟ੍ਰਿਗਰਸ",
        "tag_bulk": "ਬਲਕ ਅੱਪਲੋਡ ਹਾਰਡਨਿੰਗ",
        "tag_precision": "ਸ਼ੁੱਧ UX",
        "update_v101_title": "ਉੱਨਤ ਫਲੀਟ ਨਿਗਰਾਨੀ ਅਤੇ ਗ੍ਰੈਨਿਊਲਰ ਡੇਟਾ ਕੰਟਰੋਲ",
        "update_v101_date": "April 29, 2026 | 02:45 PM",
        "update_v101_ver": "v1.0.1 (Fleet Transparency)",
        "update_v101_desc": "ਅਸੀਂ ਡੂੰਘੀ ਸੰਚਾਲਨ ਸੂਝ ਅਤੇ ਸੁਚਾਰੂ ਡੇਟਾ ਪ੍ਰਬੰਧਨ ਪ੍ਰਦਾਨ ਕਰਨ ਲਈ ਫਲੀਟ ਪ੍ਰਬੰਧਨ ਮੋਡੀਊਲ ਨੂੰ ਮਹੱਤਵਪੂਰਨ ਤੌਰ ਤੇ ਵਧਾਇਆ ਹੈ:",
        "update_v101_b1": "ਵਧਿਆ ਹੋਇਆ ਡਰਾਈਵਰ ਰਜਿਸਟਰੀ: ਡਰਾਈਵਰ ਟੇਬਲ ਵਿੱਚ ਹੁਣ ਲਾਇਸੈਂਸ ਦੀ ਕਿਸਮ ਅਤੇ ਪਿਛਲੇ ਹਾਦਸਿਆਂ ਲਈ ਸਮਰਪਿਤ ਕਾਲਮ ਸ਼ਾਮਲ ਹਨ।",
        "update_v101_b2": "ਰਿਫਾਈਨਡ ਡੇਟਾ ਡਿਸਪਲੇ: ਇੰਟਰਫੇਸ ਨੂੰ ਫੋਕਸ ਰੱਖਣ ਲਈ ਵਾਹਨ ਪਾਸਵਰਡ ਵਰਗੇ ਬੇਲੋੜੇ ਖੇਤਰਾਂ ਨੂੰ ਹਟਾ ਦਿੱਤਾ ਗਿਆ ਹੈ।",
        "update_v101_b3": "ਬੁੱਧੀਮਾਨ ਇਨਪੁਟ ਨਿਯੰਤਰਣ: ਡਰਾਈਵਰਾਂ ਅਤੇ ਵਾਹਨਾਂ ਦੋਵਾਂ ਲਈ ਐਡਿਟ ਮੋਡੀਊਲ ਅਪਗ੍ਰੇਡ ਕੀਤੇ ਗਏ ਹਨ।",
        "update_v101_b4": "ਸੰਯੁਕਤ ਸੰਚਾਰ: ਡੁਪਲੀਕੇਟ ਫੋਨ ਸੈਕਸ਼ਨਾਂ ਨੂੰ ਮਿਲਾ ਕੇ ਡਰਾਈਵਰ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਨੂੰ ਸਰਲ ਬਣਾਇਆ ਗਿਆ ਹੈ।",
        "update_v101_b5": "ਵਿਆਪਕ CRUD ਨਿਗਰਾਨੀ: ਮੈਨੇਜਰਾਂ ਕੋਲ ਹੁਣ ਹਰੇਕ ਸਿਸਟਮ ਫੀਲਡ ਨੂੰ ਐਡਿਟ ਕਰਨ ਦਾ ਪੂਰਾ ਅਧਿਕਾਰ ਹੈ।",
        "update_v101_impact_desc": "ਇਹ ਸੁਧਾਰ ਸਾਡੇ ਮੁੱਖ ਉਪਭੋਗਤਾਵਾਂ ਲਈ ਮਾਪਣਯੋਗ ਸੁਧਾਰ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ:",
        "update_v101_i1": "ਫਲੀਟ ਮੈਨੇਜਰਾਂ ਲਈ: ਵਧੇਰੇ ਡੇਟਾ ਟੇਬਲਾਂ ਨਾਲ ਤੇਜ਼ੀ ਨਾਲ ਫੈਸਲੇ ਲੈਣਾ।",
        "update_v101_i2": "ਡੇਟਾ ਪ੍ਰਬੰਧਕਾਂ ਲਈ: ਡੇਟਾ ਐਂਟਰੀ ਦੀਆਂ ਗਲਤੀਆਂ ਵਿੱਚ ਭਾਰੀ ਕਮੀ।",
        "update_v101_i3": "ਸਪੋਰਟ ਟੀਮਾਂ ਲਈ: ਬਿਹਤਰ ਟ੍ਰਬਲਸ਼ੂਟਿੰਗ ਕੁਸ਼ਲਤਾ।",
        "tag_safety": "ਸੁਰੱਖਿਆ ਪਾਰਦਰਸ਼ਤਾ",
        "tag_consistency": "ਡੇਟਾ ਇਕਸਾਰਤਾ",
        "tag_ux": "UX ਸੁਧਾਰ",
        "tag_governance": "ਫਲੀਟ ਗਵਰਨੈਂਸ",
        "update_v100_title": "ਪੂਰਾ ਪਲੇਟਫਾਰਮ ਸੰਖੇਪ ਅਤੇ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ",
        "update_v100_date": "April 29, 2026 | 09:00 AM",
        "update_v100_ver": "v1.0.0 (Initial Launch)",
        "update_v100_desc": "Logistix ਦੇ ਪਹਿਲੇ ਸੰਸਕਰਣ ਵਿੱਚ ਤੁਹਾਡਾ ਸਵਾਗਤ ਹੈ। ਵਿਆਪਕ ਵਿਕਾਸ ਤੋਂ ਬਾਅਦ, ਅਸੀਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਡਿਜੀਟਲ ਅਤੇ AI-ਅਨੁਕੂਲ ਲੌਜਿਸਟਿਕ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਪੇਸ਼ ਕਰਨ ਵਿੱਚ ਮਾਣ ਮਹਿਸੂਸ ਕਰਦੇ ਹਾਂ।",
