        "update_v112_date": "April 30, 2026 | 10:15 AM",
        "update_v112_ver": "v1.1.2 (Linguistic Parity)",
        "update_v112_title": "ਵਿਆਪਕ ਬਹੁ-ਭਾਸ਼ਾ ਸਹਾਇਤਾ ਅਤੇ ਵਿਸ਼ਵਵਿਆਪੀ ਪਹੁੰਚਯੋਗਤਾ",
        "update_v112_desc": "ਅਸੀਂ ਪੂਰੇ ਲੌਜਿਸਟਿਕ ਪਲੇਟਫਾਰਮ ਵਿੱਚ ਪੂਰੀ ਭਾਸ਼ਾਈ ਬਰਾਬਰੀ ਹਾਸਲ ਕੀਤੀ ਹੈ।",
        "update_v112_b1": "<strong>15+ ਖੇਤਰੀ ਭਾਸ਼ਾਵਾਂ:</strong> ਹਿੰਦੀ, ਬੰਗਾਲੀ, ਗੁਜਰਾਤੀ, ਤੇਲਗੂ, ਤਾਮਿਲ, ਮਰਾਠੀ, ਕੰਨੜ, ਮਲਿਆਲਮ, ਉੜੀਆ, ਪੰਜਾਬੀ, ਅਸਾਮੀ, ਮੈਥਿਲੀ, ਸੰਥਾਲੀ ਅਤੇ ਕਸ਼ਮੀਰੀ ਲਈ ਪੂਰਾ ਸਮਰਥਨ।",
        "update_v112_b2": "<strong>ਐਂਡ-ਟੂ-ਐਂਡ ਸਥਾਨੀਕਰਨ:</strong> ਹਰ ਡੈਸ਼ਬੋਰਡ ਅਤੇ ਬਟਨ ਨੂੰ ਸਥਾਨਕ ਭਾਸ਼ਾ ਵਿੱਚ ਬਦਲਿਆ ਗਿਆ ਹੈ।",
        "update_v112_b3": "<strong>ਡਾਇਨਾਮਿਕ ਰਜਿਸਟਰੀ ਸਿੰਕ:</strong> ਪੇਜ ਰੀਲੋਡ ਕੀਤੇ ਬਿਨਾਂ ਰੀਅਲ-ਟਾਈਮ UI ਅੱਪਡੇਟ ਯਕੀਨੀ ਬਣਾਉਂਦਾ ਹੈ।",
        "update_v112_b4": "<strong>ਸਥਾਨਕ ਸਹਾਇਤਾ ਅਤੇ ਆਵਾਜ਼:</strong> ਸੁਰੱਖਿਅਤ ਡਰਾਈਵਿੰਗ ਲਈ ਵੌਇਸ ਕਮਾਂਡ ਹੁਣ ਖੇਤਰੀ ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ ਉਪਲਬਧ ਹਨ।",
        "update_v112_impact_desc": "ਵਧੇਰੇ ਉਪਭੋਗਤਾ ਹੁਣ ਪੋਰਟਲ ਨੂੰ ਵਧੇਰੇ ਸੁਤੰਤਰ ਰੂਪ ਵਿੱਚ ਐਕਸੈਸ ਕਰ ਸਕਦੇ ਹਨ ਅਤੇ ਆਪਣੀ ਮਾਤૃਭਾਸ਼ਾ ਵਿੱਚ ਵਿਸ਼ਵਾਸ ਨਾਲ ਕੰਮ ਕਰ ਸਕਦੇ ਹਨ।",
        "update_v112_i1": "ਵਿਸ਼ਵਵਿਆਪੀ ਪਹੁੰਚ: ਸਾਰੇ ਖੇਤਰਾਂ ਦੇ ਉਪਭੋਗਤਾ ਹੁਣ ਆਪਣੀ ਮਾਤ੍ਰਭਾਸ਼ਾ ਵਿੱਚ ਪੋਰਟਲ ਦੀ ਵਰਤੋਂ ਕਰ ਸਕਦੇ ਹਨ।",
        "update_v112_i2": "ਕਾਰਜਸ਼ੀਲ ਸ਼ਮੂਲੀਅਤ: ਡਰਾਈਵਰ ਹੁਣ ਸੁਤੰਤਰ ਤੌਰ ਤੇ ਨੇਵੀਗੇਟ ਕਰ ਸਕਦੇ ਹਨ ਅਤੇ ਆਪਣਾ ਵਾਲਿਟ ਪ੍ਰਬੰਧਿਤ ਕਰ ਸਕਦੇ ਹਨ।",
        "update_v112_i3": "ਪਾਰਦਰਸ਼ਤਾ: ਸਥਾਨਕ ਵਿੱਤੀ ਹੈਡਰ ਲੈਣ-ਦੇਣ ਵਿੱਚ ਵਿਸ਼ਵਾਸ ਵਧਾਉਂਦੇ ਹਨ।",
        "update_v112_i4": "ਵਿਸ਼ਵ ਪੱਧਰੀ ਮਿਆਰ: ਵਿਸ਼ਵ ਪੱਧਰੀ ਤਕਨਾਲੋਜੀ ਅਤੇ ਖੇਤਰੀ ਅਨੁਭਵ ਦਾ ਸੁਮੇਲ।",
        "tag_localization": "ਸਥਾਨੀਕਰਨ",
        "tag_accessibility": "Universal Access",
        "tag_multi_lingual": "Multi-Lingual",
        "otp_wait_msg": "Please wait for the timer to finish before requesting again.",
        "otp_sending": "ਕਿਰਪਾ ਕਰਕੇ ਉਡੀਕ ਕਰੋ, OTP ਭੇਜਿਆ ਜਾ ਰਿਹਾ ਹੈ...",
        "otp_sent_to_email": "OTP sent to your email.",
        "update_v113_title": "ਡਰੋਨ ਫਲੀਟ ਏਕੀਕਰਣ ਅਤੇ ਸੁਰੱਖਿਆ ਮਜ਼ਬੂਤੀ",
        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "ਇਹ ਅਪਡੇਟ ਖੁਦਮੁਖਤਿਆਰ ਡਰੋਨ ਫਲੀਟਾਂ ਨੂੰ ਇੱਕ ਪ੍ਰਾਇਮਰੀ ਟ੍ਰਾਂਸਪੋਰਟ ਮੋਡ ਵਜੋਂ ਪੇਸ਼ ਕਰਦਾ ਹੈ ਅਤੇ ਖਾਤਾ ਸੁਰੱਖਿਆ ਨੂੰ ਮਜ਼ਬੂਤ ਕਰਦਾ ਹੈ:",
        "update_v113_b1": "ਡਰੋਨ ਫਲੀਟ ਪ੍ਰਬੰਧਨ: ਡਰੋਨ ਹੁਣ ਸਮਰਪਿਤ ਰਜਿਸਟ੍ਰੇਸ਼ਨ, ਲਾਇਸੈਂਸ ਟ੍ਰੈਕਿੰਗ ਅਤੇ ਬਲਕ ਅਪਲੋਡ ਸਹਾਇਤਾ ਦੇ ਨਾਲ ਇੱਕ ਪ੍ਰਮੁੱਖ ਟ੍ਰਾਂਸਪੋਰਟ ਮੋਡ ਹਨ।",
        "update_v113_b2": "ਸਮਾਰਟ ਡਰੋਨ ਸਹਾਇਕ: ਨਿਰਦੇਸ਼ਿਤ ਸਟੈਪ-ਬਾਈ-ਸਟੈਪ ਚੈਟ ਇੰਟਰਫੇਸ ਰਾਹੀਂ ਡਰੋਨ ਆਨਬੋਰਡ ਕਰੋ।",
        "update_v113_b3": "ਬਿਹਤਰ OTP ਭਰੋਸੇਯੋਗਤਾ: ਸਾਈਨਅਪ, ਖਾਤਾ ਮਿਟਾਉਣ ਅਤੇ ਟ੍ਰੈਕਿੰਗ ਫਲੋਅ ਵਿੱਚ OTP ਬੇਨਤੀਆਂ ਵਿੱਚ ਸਿਸਟਮ ਹੈਂਗਿੰਗ ਸਮੱਸਿਆਵਾਂ ਨੂੰ ਹੱਲ ਕੀਤਾ ਗਿਆ।",
        "update_v113_b4": "ਸੁਰੱਖਿਅਤ ਖਾਤਾ ਮਿਟਾਉਣਾ: ਵੱਧ ਤੋਂ ਵੱਧ ਸੁਰੱਖਿਆ ਲਈ ਖਾਤਾ ਹਟਾਉਣ ਲਈ ਹੁਣ ਮੈਨੇਜਰ ਪਾਸਵਰਡ ਅਤੇ OTP ਨਾਲ ਮਲਟੀ-ਫੈਕਟਰ ਵੈਰੀਫਿਕੇਸ਼ਨ ਦੀ ਲੋੜ ਹੈ।",
        "update_v113_impact_desc": "ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਵਧੇਰੇ ਬਹੁਮੁਖੀ ਫਲੀਟ ਅਤੇ ਵਧੇਰੇ ਭਰੋਸੇਮੰਦ ਪ੍ਰਮਾਣਿਕਤਾ ਅਨੁਭਵ ਤੋਂ ਲਾਭ ਹੋਵੇਗਾ:",
        "update_v113_i1": "ਬਹੁਮੁਖੀ ਲੌਜਿਸਟਿਕਸ: ਇੱਕ ਸੰਯੁਕਤ 'Drivers & Fleet' ਡੈਸ਼ਬੋਰਡ ਤੋਂ ਧਰਤੀ ਅਤੇ ਹਵਾਈ ਦੋਵਾਂ ਸੰਪਤੀਆਂ ਦਾ ਨਿਰਵਿਘਨ ਪ੍ਰਬੰਧਨ ਕਰੋ।",
        "update_v113_i2": "ਅਸਾਨ ਆਨਬੋਰਡਿੰਗ: ਸਮਾਰਟ ਸਹਾਇਕ ਗੁੰਝਲਦਾਰ ਰਜਿਸਟ੍ਰੇਸ਼ਨਾਂ ਵਿੱਚ ਤੁਹਾਡੀ ਅਗਵਾਈ ਕਰਦੇ ਹਨ, ਡੇਟਾ ਐਂਟਰੀ ਦੀਆਂ ਗਲਤੀਆਂ ਨੂੰ ਖਤਮ ਕਰਦੇ ਹਨ।",
        "update_v113_i3": "ਭਰੋਸੇਯੋਗ ਪ੍ਰਮਾਣਿਕਤਾ: ਸਥਾਨਕ OTP ਸੁਨੇਹੇ ਅਤੇ ਬਿਹਤਰ ਬੈਕਐਂਡ ਸਿੰਕ੍ਰੋਨਾਈਜ਼ੇਸ਼ਨ ਇਹ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹਨ ਕਿ ਤੁਸੀਂ ਪੁਸ਼ਟੀਕਰਨ ਦੌਰਾਨ ਕਦੇ ਵੀ ਫਸੇ ਨਹੀਂ ਰਹੋਗੇ।",
