        "update_v100_title": "ಸಂಪೂರ್ಣ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅವಲೋಕನ ಮತ್ತು ವೈಶಿಷ್ಟ್ಯಗಳು",
        "update_v100_date": "April 29, 2026 | 09:00 AM",
