        "update_v112_date": "April 30, 2026 | 10:15 AM",
        "update_v112_ver": "v1.1.2 (Linguistic Parity)",
        "update_v112_title": "సమగ్ర బహుళ భాషా మద్దతు మరియు సార్వత్రిక ప్రాప్యత",
        "update_v112_desc": "మేము మొత్తం లాజిస్టిక్స్ ప్లాట్‌ఫారమ్‌లో పూర్తి భాషాపరమైన సమానత్వాన్ని సాధించాము.",
        "update_v112_b1": "<strong>15+ ప్రాంతీయ భాషలు:</strong> హిందీ, బెంగాలీ, గుజరాతీ, తెలుగు, తమిళం, మరాఠీ, కన్నడ, మలయాళం, ఒడియా, పంజాబీ, అస్సామీ, మైథిలి, సంతాలి మరియు కాశ్మీరీలకు పూర్తి మద్దతు జోడించబడింది.",
        "update_v112_b2": "<strong>ఎండ్-టు-ఎండ్ లోకలైజేషన్:</strong> ప్రతి డాష్‌బోర్డ్, టేబుల్ హెడర్, బటన్ మరియు సిస్టమ్ నోటిఫికేషన్ స్థానీకరించబడ్డాయి.",
        "update_v112_b3": "<strong>డైనమిక్ రిజిస్ట్రీ సింక్:</strong> పేజీ రీలోడ్ లేకుండా రియల్ టైమ్ UI అప్‌డేట్‌లను నిర్ధారించే కేంద్రీకృత అనువాద ఇంజిన్.",
        "update_v112_b4": "<strong>స్థానికీకరించిన సహాయం & వాయిస్:</strong> సురక్షితమైన డ్రైవర్ కార్యకలాపాల కోసం వాయిస్ కమాండ్‌లు ఇప్పుడు అందుబాటులో ఉన్నాయి.",
        "update_v112_impact_desc": "ఎక్కువ మంది వినియోగదారులు ఇప్పుడు పోర్టల్‌ను మరింత స్వేచ్ఛగా యాక్సెస్ చేయవచ్చు మరియు వారి మాతృభాషలో విశ్వాసంతో పని చేయవచ్చు.",
        "update_v112_i1": "సార్వత్రిక యాక్సెస్: భారతదేశంలోని అన్ని ప్రాంతాల వినియోగదారులు ఇప్పుడు పోర్టల్‌ను వారి మాతృభాషలో మరింత స్వేచ్ఛగా యాక్సెస్ చేయవచ్చు.",
        "update_v112_i2": "ఆపరేషనల్ ఇంక్లూజన్: డ్రైవర్లు ఇప్పుడు స్వతంత్రంగా నావిగేట్ చేయవచ్చు మరియు వారి వాలెట్‌లను నిర్వహించవచ్చు.",
        "update_v112_i3": "తగ్గిన ఘర్షణ: స్థానికీకరించిన ఆర్థిక హెడర్‌లు లావాదేవీలలో పారదర్శకతను నిర్ధారిస్తాయి.",
        "update_v112_i4": "గ్లోబల్ స్టాండర్డ్స్, లోకల్ ఫీల్: ప్రపంచ స్థాయి లాజిస్టిక్స్ టెక్నాలజీని ప్రాంతీయ అనుభవంతో మిళితం చేస్తుంది.",
