        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "ఈ అప్‌డేట్ అటానమస్ డ్రోన్ ఫ్లీట్‌లను ప్రాథమిక రవాణా మోడ్‌గా పరిచయం చేస్తుంది మరియు ఖాతా భద్రతను బలపరుస్తుంది:",
        "update_v113_b1": "డ్రోన్ ఫ్లీట్ మేనేజ్మెంట్: డ్రోన్లు ఇప్పుడు ప్రధాన రవాణా మోడ్, ప్రత్యేక రిజిస్ట్రేషన్, లైసెన్స్ ట్రాకింగ్ మరియు బల్క్ అప్‌లోడ్ మద్దతుతో.",
        "update_v113_b2": "స్మార్ట్ డ్రోన్ అసిస్టెంట్: గైడెడ్ స్టెప్-బై-స్టెప్ చాట్ ఇంటర్‌ఫేస్ ద్వారా డ్రోన్లను ఆన్‌బోర్డ్ చేయండి.",
        "update_v113_b3": "మెరుగైన ఓటీపీ విశ్వసనీయత: సైన్అప్, ఖాతా తొలగింపు మరియు ట్రాకింగ్ ఫ్లోలలో ఓటీపీ అభ్యర్థనలలో సమస్యలను పరిష్కరించాము.",
        "update_v113_b4": "సురక్షిత తొలగింపు వర్క్ ఫ్లో: గరిష్ట భద్రత కోసం ఖాతా తొలగింపుకు ఇప్పుడు మల్టీ-ఫ్యాక్టర్ అథెంటికేషన్ అవసరం.",
        "update_v113_impact_desc": "వినియోగదారులు మరింత బహుముఖ ఫ్లీట్ మరియు నమ్మకమైన ప్రామాణీకరణ అనుభవం నుండి ప్రయోజనం పొందుతారు:",
        "update_v113_i1": "బహుముఖ లాజిస్టిక్స్: ఏకీకృత 'Drivers & Fleet' డ్యాష్‌బోర్డ్ నుండి భూగోళ మరియు వైమానిక ఆస్తులను సజావుగా నిర్వహించండి.",
        "update_v113_i2": "సులభమైన ఆన్‌బోర్డింగ్: స్మార్ట్ అసిస్టెంట్లు సంక్లిష్ట రిజిస్ట్రేషన్ల ద్వారా మీకు మార్గనిర్దేశం చేస్తారు, డేటా ఎంట్రీ లోపాలను తొలగిస్తారు.",
        "update_v113_i3": "నమ్మకమైన ప్రామాణీకరణ: స్థానిక ఓటీపీ సందేశాలు మరియు మెరుగైన బ్యాకెండ్ సింక్రొనైజేషన్ మీరు ధృవీకరణ సమయంలో ఎప్పుడూ చిక్కుకోకుండా చూస్తాయి.",
