        "update_v111_title": "ইউনিফাইড স্মাৰ্ট এছিষ্টেণ্ট ট্ৰিগাৰ আৰু বাল্ক ডাটা হার্ডেনিং",
        "update_v111_date": "April 29, 2026 | 09:00 PM",
        "update_v111_ver": "v1.1.1 (Smart Assistant)",
        "update_actual_updates": "১) প্ৰধান আপডেটসমূহ",
        "update_v111_desc": "আমি সমগ্ৰ মেনেজাৰ মেনেজমেণ্ট চুইটত গভীৰ AI একত্ৰীকৰণ আৰম্ভ কৰিছোঁ:",
        "update_v111_b1": "ইউনিভাৰ্চেল স্মাৰ্ট এছিষ্টেণ্ট বুটাম: ড্ৰাইভাৰ, বাহন আৰু শ্বিপমেণ্ট পঞ্জীয়ন শাখাত পোনপটীয়াকৈ স্মাৰ্ট এছিষ্টেণ্ট ট্ৰিগাৰ অন্তৰ্ভুক্ত কৰা হৈছে।",
        "update_v111_b2": "গাইড কৰা ইণ্টাৰেক্টিভ প্ৰবাহ: তথ্য সংগ্ৰহৰ বাবে চাটবটে এতিয়া আপোনাক খোজ খোজকৈ সহায় কৰিব।",
        "update_v111_b3": "পুনৰ সংজ্ঞায়িত বাল্ক আপলোড আন্তঃগাঁথনি: শ্বিপমেণ্ট, ড্ৰাইভাৰ আৰু বাহনৰ বাবে বাল্ক আপলোড সুবিধাসমূহ উন্নত কৰা হৈছে।",
        "update_v111_b4": "সুৰক্ষা বুদ্ধিমত্তা কেপচাৰ: ইণ্টাৰেক্টিভ প্ৰবাহে এতিয়া সুৰক্ষা সম্পৰ্কীয় ড্ৰাইভাৰ মেট্ৰিক্স অন্তৰ্ভুক্ত কৰে।",
        "update_impact_benefits": "২) প্ৰভাৱ আৰু ব্যৱহাৰকাৰীৰ সুবিধাসমূহ",
        "update_v111_impact_desc": "This version focuses on making the platform more accessible and precision-oriented:",
        "update_v111_i1": "Enhanced Interactivity: Moving away from static forms makes the platform significantly more user-friendly.",
        "update_v111_i2": "Precision & Accuracy: Guided flows eliminate guesswork. Interactive dropdowns and automated formatting ensure accuracy.",
        "update_v111_i3": "Accelerated Operations: Integrated map pickers and strictly enforced dropdowns enable much faster data entry.",
        "update_v111_i4": "Verified Bulk Reliability: Redefined bulk tools ensure scaling your fleet is a smooth, error-free experience.",
        "tag_chatbot": "ইণ্টাৰেক্টিভ চাটবট",
        "tag_triggers": "স্মাৰ্ট ট্ৰিগাৰ",
        "tag_bulk": "বাল্ক আপলোড হার্ডেনিং",
        "tag_precision": "প্ৰিচিচন UX",
        "update_v101_title": "উন্নত ফ্লিট তদাৰক আৰু গ্ৰেনুলাৰ ডাটা নিয়ন্ত্ৰণ",
        "update_v101_date": "April 29, 2026 | 02:45 PM",
        "update_v101_ver": "v1.0.1 (Fleet Transparency)",
        "update_v101_desc": "আমি গভীৰ কাৰ্যক্ষম অন্তৰ্দৃষ্টি আৰু মসৃণ ডাটা মেনেজমেন্ট প্ৰদান কৰিবলৈ ফ্লিট মেনেজমেন্ট মডিউলটো বুজন পৰিমাণে উন্নত কৰিছোঁ:",
        "update_v101_b1": "উন্নত ড্ৰাইভাৰ পঞ্জীয়ন: ড্ৰাইভাৰ টেবুলত এতিয়া লাইচেঞ্চৰ ধৰণ আৰু অতীতৰ দুৰ্ঘটনাৰ বাবে উৎসৰ্গিত স্তম্ভ অন্তৰ্ভুক্ত কৰা হৈছে।",
        "update_v101_b2": "পৰিশোধিত ডাটা প্ৰদৰ্শন: ইণ্টাৰফেচটো ফকাচ কৰি ৰাখিবলৈ বাহনৰ পাছৱৰ্ডৰ দৰে অপ্ৰয়োজনীয় ফিল্ডসমূহ আঁতৰোৱা হৈছে।",
        "update_v101_b3": "বুদ্ধিমান ইনপুট নিয়ন্ত্ৰণ: ড্ৰাইভাৰ আৰু বাহন উভয়ৰে বাবে এডিট মডিউলসমূহ উন্নীত কৰা হৈছে।",
        "update_v101_b4": "একত্ৰিত যোগাযোগ: ডুপ্লিকেট ফোন চেক্সনসমূহ একত্ৰিত কৰি ড্ৰাইভাৰ পঞ্জীয়ন সৰল কৰা হৈছে।",
        "update_v101_b5": "ব্যাপক CRUD তদাৰক: মেনেজাৰসকলৰ ওচৰত এতিয়া প্ৰতিটো চিষ্টেম ফিল্ড এডিট কৰাৰ সম্পূৰ্ণ কৰ্তৃত্ব আছে।",
        "update_v101_impact_desc": "এই সংশোধনসমূহে আমাৰ মূল ব্যৱহাৰকাৰীসকলৰ বাবে জোখা পৰা উন্নতি প্ৰদান কৰে:",
        "update_v101_i1": "ফ্লিট মেনেজাৰসকলৰ বাবে: সমৃদ্ধ ডাটা টেবুলৰ সহায়ত দ্ৰুত সিদ্ধান্ত গ্ৰহণ।",
        "update_v101_i2": "ডাটা প্ৰশাসকসকলৰ বাবে: ডাটা এণ্ট্ৰি ত্ৰুটিৰ ব্যাপক হ্ৰাস।",
        "update_v101_i3": "সাপৰ্ট টিমৰ বাবে: উন্নত সমস্যা সমাধানৰ দক্ষতা।",
