        "update_v113_title": "ড্ৰোন ফ্লিট একত্ৰীকৰণ আৰু সুৰক্ষা সুদৃঢ়কৰণ",
        "update_v113_date": "April 30, 2026 | 05:00 PM",
        "update_v113_ver": "v1.1.3 (Drones & Security)",
        "update_v113_desc": "এই আপডেটটোৱে স্বায়ত্তশাসিত ড্ৰোন ফ্লিটসমূহক এক প্ৰাথমিক পৰিবহণ মোড হিচাপে পৰিচয় কৰাই দিয়ে আৰু একাউণ্টৰ সুৰক্ষা শক্তিশালী কৰে:",
        "update_v113_b1": "ড্ৰোন ফ্লিট পৰিচালনা: ড্ৰোনসমূহ এতিয়া উৎসর্গিত পঞ্জীয়ন, লাইচেঞ্চ ট্ৰেকিং আৰু বাল্ক আপলোড সমৰ্থনৰ সৈতে এক মুখ্য পৰিবহণ মোড।",
        "update_v113_b2": "স্মাৰ্ট ড্ৰোন সহায়ক: নিৰ্দেশিত পদক্ষেপ অনুসৰি চেট ইন্টাৰফেচৰ জৰিয়তে ড্ৰোনসমূহ অনবোৰ্ড কৰক।",
        "update_v113_b3": "উন্নত OTP বিশ্বাসযোগ্যতা: ছাইনআপ, একাউণ্ট ডিলিট আৰু ট্ৰেকিং ফ্ল’ত OTP অনুৰোধত চিষ্টেম হেঙিঙৰ সমস্যা সমাধান কৰা হৈছে।",
        "update_v113_b4": "সুৰক্ষিত একাউণ্ট ডিলিট: সৰ্বাধিক সুৰক্ষাৰ বাবে একাউণ্ট আঁতৰাবলৈ এতিয়া মেনেজাৰ পাছৱৰ্ড আৰু OTP ৰ সৈতে মাল্টি-ফেক্টৰ ভেৰিফিকেচনৰ প্ৰয়োজন।",
        "update_v113_impact_desc": "ব্যৱহাৰকাৰীসকলে অধিক বহুমুখী ফ্লিট আৰু অধিক নিৰ্ভৰযোগ্য প্ৰমাণীকৰণ অভিজ্ঞতাৰ পৰা লাভান্বিত হ’ব:",
        "update_v113_i1": "বহুমুখী লজিষ্টিক: একত্ৰিত 'Drivers & Fleet' ডেশ্ববৰ্ডৰ পৰা স্থল আৰু আকাশী দুয়োটা সম্পদ নিৰৱচ্ছিন্নভাৱে পৰিচালনা কৰক।",
        "update_v113_i2": "সহজ অনবোৰ্ডিং: স্মাৰ্ট সহায়কসকলে আপোনাক জটিল পঞ্জীয়নৰ মাজেৰে গাইড কৰে, যিয়ে ডাটা এন্ট্ৰিৰ ত্ৰুটি দূৰ কৰে।",
        "update_v113_i3": "নিৰ্ভৰযোগ্য প্ৰমাণীকৰণ: স্থানীয় OTP বাৰ্তা আৰু উন্নত বেকএণ্ড চিনক্ৰনাইজেচনে নিশ্চিত কৰে যে আপুনি ভেৰিফিকেচনৰ সময়ত কেতিয়াও আৱদ্ধ নহয়।",
