        "update_v111_title": "एकीकृत स्मार्ट सहायक आ बल्क डेटा हार्डनिंग",
        "update_v111_date": "April 29, 2026 | 09:00 PM",
        "update_v111_ver": "v1.1.1 (Smart Assistant)",
        "update_actual_updates": "1) मुख्य अपडेट",
        "update_v111_desc": "मैनेजर क लेल AI सहायक आ बल्क डेटा अपलोड सुविधा मे सुधार कएल गेल अछि।",
        "update_v111_b1": "यूनिवर्सल स्मार्ट सहायक बटन: ड्राइवर, वाहन आ शिपमेंट पंजीकरण खंड में सीधे स्मार्ट सहायक ट्रिगर जोड़ने अछि।",
        "update_v111_b2": "निर्देशित इंटरएक्टिव प्रवाह: चैटबॉट आब जानकारी एकत्र करबाक लेल अहाँक चरण-दर-चरण संवादक माध्यम सं मदद करत।",
        "update_v111_b3": "पुनर्परिभाषित बल्क अपलोड बुनियादी ढाँचा: शिपमेंट, ड्राइवर आ वाहनक लेल बल्क अपलोड विशेषताक अनुकूलन कएल अछि।",
        "update_v111_b4": "सुरक्षा इंटेलिजेंस कैप्चर: इंटरएक्टिव प्रवाह आब सुरक्षा सं संबंधित ड्राइवर मेट्रिक्स के निर्बाध रूप सं शामिल करैत अछि।",
        "update_impact_benefits": "2) प्रभाव आरू उपयोगकर्ताक लाभ",
        "update_v111_impact_desc": "This version focuses on making the platform more accessible and precision-oriented:",
        "update_v111_i1": "Enhanced Interactivity: Moving away from static forms makes the platform significantly more user-friendly.",
        "update_v111_i2": "Precision & Accuracy: Guided flows eliminate guesswork. Interactive dropdowns and automated formatting ensure accuracy.",
        "update_v111_i3": "Accelerated Operations: Integrated map pickers and strictly enforced dropdowns enable much faster data entry.",
        "update_v111_i4": "Verified Bulk Reliability: Redefined bulk tools ensure scaling your fleet is a smooth, error-free experience.",
        "tag_chatbot": "Interactive Chatbot",
        "tag_triggers": "Smart Triggers",
        "tag_bulk": "Bulk Upload Hardening",
        "tag_precision": "Precision UX",
        "update_v101_title": "उन्नत फ्लीट निगरानी आ डेटा नियंत्रण",
        "update_v101_date": "April 29, 2026 | 02:45 PM",
        "update_v101_ver": "v1.0.1 (Fleet Transparency)",
        "update_v101_desc": "ड्राइवर आ गाड़ी के प्रबंधन लेल बेहतर कंट्रोल आ डेटा सुरक्षा।",
        "update_v101_b1": "बेहतर ड्राइवर रजिस्ट्री: ड्राइवर टेबल में आब लाइसेंसक प्रकार आ पिछला दुर्घटनाक लेल समर्पित कॉलम अछि।",
        "update_v101_b2": "परिष्कृत डेटा प्रदर्शन: इंटरफेस के केंद्रित रखबाक लेल वाहन पासवर्ड सन अनावश्यक फील्ड हटा देल गेल अछि।",
        "update_v101_b3": "बुद्धिमान इनपुट नियंत्रण: ड्राइवर आ वाहन दुनूक लेल एडिट मॉड्यूल अपग्रेड कएल गेल अछि।",
        "update_v101_b4": "एकीकृत संचार: ड्राइवर पंजीकरण के सरल बनाओल गेल अछि।",
        "update_v101_b5": "व्यापक CRUD निरीक्षण: मैनेजर लग आब प्रत्येक सिस्टम फील्ड के एडिट करबाक पूर्ण अधिकार अछि।",
        "update_v101_impact_desc": "These refinements translate to measurable improvements for our core user base:",
        "update_v101_i1": "For Fleet Managers: Faster decision-making with enriched data tables.",
        "update_v101_i2": "For Data Administrators: Drastic reduction in data entry errors.",
        "update_v101_i3": "For Support Teams: Improved troubleshooting efficiency.",
